insert into public.day_block_translations (id, block_id, lang, title, description, includes, excludes, reviewed) values ('627537c6-6c29-533d-8ab1-23b86c86b9ce', '63ca6183-6ab8-55fb-8ad9-78f3fd048d75', 'es', '(Bolivia) – Cementerio de Trenes · Ruta altiplánica (Cañapa/Hedionda) · Desierto de Siloli · Regreso a zona Hedionda', 'Salida hacia Uyuni para visitar el Cementerio de Trenes, un ícono fotográfico de la historia ferroviaria del altiplano. Luego se continúa hacia el mirador del Volcán Ollagüe y se avanza hacia el sur, con paradas en paisajes de altura y lagunas altiplánicas como Cañapa, además de sectores cercanos a Hedionda. Durante la tarde se atraviesa el Desierto de Siloli, regresando posteriormente a la zona de Hedionda para el alojamiento.
