insert into public.day_block_translations (id, block_id, lang, title, description, includes, excludes, reviewed) values ('206b88b5-4326-5a3e-9b11-03bb68308793', '9984d2d1-b938-5983-b0de-ed48e64e1c47', 'es', '(Bolivia/Chile) – Retorno a San Pedro de Atacama', 'Tras el desayuno, salida desde el hotel rumbo a la frontera de Hito Cajón. Visitamos los Géiseres Sol de Mañana y, después del almuerzo, se realiza el cruce y el regreso a San Pedro de Atacama (Chile). Tras el regreso a San Pedro, se contempla una pausa para compras y almuerzo libre y por la tarde se continúa con la excursión a Laguna Cejar, conocida por sus aguas de alta salinidad y su entorno único en pleno desierto.
