insert into public.day_block_translations (id, block_id, lang, title, description, includes, excludes, reviewed) values ('23e45a1e-7e55-58f5-bd6e-7c37b688ae2c', 'c711b6c7-8384-58a8-9bf1-806c5f6ef844', 'es', 'Cruce Hito Cajón · Lagunas Altiplánicas · Villamar', 'Salida temprano desde San Pedro de Atacama rumbo a la frontera Hito Cajón para ingresar al altiplano boliviano. Desde los primeros kilómetros, el paisaje cambia por completo: se visitan la Laguna Blanca y la Laguna Verde, con el volcán Licancabur como telón de fondo, y luego el Desierto de Dalí, un escenario surreal de formaciones y colores. La ruta continúa hacia Uyuni.
