insert into public.day_block_translations (id, block_id, lang, title, description, includes, excludes, reviewed) values ('513e979b-dea6-564a-8d32-448349a32b23', 'b5ef56b5-a3ad-5c84-934c-3a4808b1d7f7', 'es', '(Bolivia) –Full day en el Salar de Uyuni · Isla Incahuasi · Atardecer', 'Salar de Uyuni para vivir la experiencia completa del desierto de sal, incluyendo la visita a la Isla Incahuasi, con caminata y vistas panorámicas entre cactus gigantes. El almuerzo es un Apthapi servido en el salar y, al final del día, se vive uno de los momentos más especiales del programa: cóctel privado al atardecer sobre el salar.
