insert into public.day_block_translations (id, block_id, lang, title, description, includes, excludes, reviewed) values ('88a08df8-c099-51d1-b10f-fa3397bbbfda', '3fede8da-f71c-5220-8f5e-dfcd29c0a403', 'es', '(Bolivia/Chile) – Retorno a San Pedro de Atacama', 'Tras el desayuno, salida desde el hotel rumbo a la frontera de Hito Cajón. Visitamos los Géiseres Sol de Mañana y, después del almuerzo, se realiza el cruce y el regreso a San Pedro de Atacama (Chile). Tras el regreso a San Pedro, se contempla una pausa para compras y almuerzo libre y por la tarde se continúa con la excursión a Laguna Cejar, conocida por sus aguas de alta salinidad y su entorno único en pleno desierto.
