insert into public.day_block_translations (id, block_id, lang, title, description, includes, excludes, reviewed) values ('e97fc66a-0997-5fd5-8549-20ca7562da31', '42b5e981-7215-5d31-a888-d74018241683', 'es', 'Cruce Hito Cajón · Lagunas Altiplánicas', 'Salida temprano desde San Pedro de Atacama rumbo a la frontera Hito Cajón para ingresar al altiplano boliviano. Desde los primeros kilómetros, el paisaje cambia por completo: se visitan la Laguna Blanca y la Laguna Verde, con el volcán Licancabur como telón de fondo, y luego el Desierto de Dalí, un escenario surreal de formaciones y colores. La ruta continúa hacia Uyuni.
