insert into public.day_block_translations (id, block_id, lang, title, description, includes, excludes, reviewed) values ('1ace0329-bb9b-5c1a-b898-838b4e6fce33', '04b2b7cd-4a76-5a36-820d-34dd42c7bcdc', 'es', 'Full day en el Salar de Uyuni · Isla Incahuasi · Atardecer', 'Salar de Uyuni para vivir la experiencia completa del desierto de sal, incluyendo la visita a la Isla Incahuasi, con caminata y vistas panorámicas entre cactus gigantes. El almuerzo es un Apthapi servido en el salar y, al final del día, se vive uno de los momentos más especiales del programa: cóctel privado al atardecer sobre el salar.
