insert into public.day_block_translations (id, block_id, lang, title, description, includes, excludes, reviewed) values ('c916b6c0-daf2-5597-b8dc-af3df88453c7', 'b375a7c2-5503-58a7-b36b-8ede9f965ca6', 'es', 'Cementerio de Trenes  · Desierto de Siloli · Regreso a zona Hedionda', 'Salida hacia Uyuni para visitar el Cementerio de Trenes, un ícono fotográfico de la historia ferroviaria del altiplano. Luego se continúa hacia el mirador del Volcán Ollagüe y se avanza hacia el sur, con paradas en paisajes de altura y lagunas altiplánicas como Cañapa, además de sectores cercanos a Hedionda. Durante la tarde se atraviesa el Desierto de Siloli, regresando posteriormente a la zona de Hedionda para el alojamiento.
