insert into public.day_block_translations (id, block_id, lang, title, description, includes, excludes, reviewed) values ('445bc0bd-0e0f-557b-abe9-090199ee33cb', '36a85551-24f4-54b9-b27a-0da3810cce99', 'es', 'Salar de Uyuni · Cóctel al Atardecer', 'Visita el pueblo artesanal de Colchani antes de ingresar al inmenso Salar de Uyuni. Disfruta de un almuerzo en medio del salar y luego explora la famosa Isla Incahuasi, hogar de cactus gigantes y formaciones de coral fosilizado. Almuerzo tipo apthapi en el salar. Luego continuaremos hacia las impresionantes Lagunas Altiplánicas — Cañapa, Ramaditas, Honda y Hedionda — hábitat natural de cientos de flamencos dentro de un extraordinario paisaje andino. Posteriormente cruzaremos el Desierto de Siloli, rodeado de volcanes de colores y extensas planicies de altura.
