insert into public.day_block_translations (id, block_id, lang, title, description, includes, excludes, reviewed) values ('32e2ed33-4d1e-5d38-b754-b22726929839', 'b0bc90f4-eab7-54c3-8f20-0413d0d578a2', 'es', 'Sol de la Mañana · Hito Cajón · San Pedro de Atacama', 'Salida temprano para visitar los géiseres de Sol de la Mañana, ubicados a casi 5.000 metros sobre el nivel del mar, donde la actividad geotérmica crea fumarolas y pozas de barro hirviendo. Continuación hacia las Termas de Polques, donde podrás relajarte en aguas termales naturales. Luego cruzarás el surrealista Desierto Dalí y visitarás la Laguna Verde y la Laguna Blanca al pie del volcán Licancabur. Traslado en vehículo chileno desde la frontera boliviana (Hito Cajón) hacia San Pedro de Atacama antes de las 17:00 hrs.', 'Desayuno · Almuerzo', '- Tasas fronterizas y migratorias
