insert into public.day_block_translations (id, block_id, lang, title, description, includes, excludes, reviewed) values ('c8e8c5ca-6c80-58c8-817e-a9dc7a2f7b88', '67a6c390-91b3-5cfa-b80a-8d806eb52d3f', 'es', 'Sol de la Mañana · Hito Cajón  · San Pedro de Atacama', 'Salida temprano para visitar los géiseres de Sol de la Mañana, ubicados a casi 5.000 metros sobre el nivel del mar, donde la actividad geotérmica crea fumarolas y pozas de barro hirviendo. Continuación hacia las Termas de Polques, donde podrás relajarte en aguas termales naturales. Luego cruzarás el surrealista Desierto Dalí y visitarás la Laguna Verde y la Laguna Blanca al pie del volcán Licancabur. Traslado en vehículo chileno desde la frontera boliviana (Hito Cajón) hacia San Pedro de Atacama antes de las 17:00 hrs.', 'Desayuno · Almuerzo · Cóctel', '- Tasas fronterizas y migratorias
