insert into public.day_block_translations (id, block_id, lang, title, description, includes, excludes, reviewed) values ('785ad14b-f490-551c-98ec-d5a50b404530', 'd6c157c9-37df-5aaa-8b7a-0595fe8bb95a', 'es', 'Lagunas Altiplánicas · Desierto de Siloli', 'Salida desde tu hotel en San Pedro de Atacama (Chile), cruzando la frontera por Hito Cajón, donde abordarán un vehículo 4x4 para comenzar esta aventura por los paisajes más espectaculares del altiplano boliviano. Durante el día visitarás la Laguna Blanca, Laguna Verde, el surrealista Desierto Dalí, el campo geotérmico de los Géiseres Sol de Mañana y la espectacular Laguna Colorada antes de continuar hacia Villamar.
