insert into public.day_block_translations (id, block_id, lang, title, description, includes, excludes, reviewed) values ('22de05c1-7698-53cd-963f-aec553f60203', 'bba0cc92-3509-57b4-98bf-0e43ed1835f2', 'es', 'Valle de las Rocas · Cañón de la Anaconda', 'Salida hacia el espectacular Valle de las Rocas, seguido de un recorrido por el impresionante Cañón de la Anaconda, formado por siglos de erosión natural. El día termina en Uyuni con una visita al icónico Cementerio de Trenes. Por la tarde, disfruta de una experiencia privada de cóctel al atardecer, rodeado por el infinito horizonte blanco del desierto de sal.
