insert into public.day_block_translations (id, block_id, lang, title, description, includes, excludes, reviewed) values ('8632205f-e4b9-5e1a-9cdd-f81a4c40e1c1', '7ef34805-c1a6-5335-98f9-b9ed92055e6b', 'es', 'Valle de las Rocas · Cañón de la Anaconda', 'Salida hacia el espectacular Valle de las Rocas, seguido de un recorrido por el impresionante Cañón de la Anaconda, formado por siglos de erosión natural. El día termina en Uyuni con una visita al icónico Cementerio de Trenes. Por la tarde, disfruta de una experiencia privada de cóctel al atardecer, rodeado por el infinito horizonte blanco del desierto de sal.
