insert into public.day_block_translations (id, block_id, lang, title, description, includes, excludes, reviewed) values ('b26cfcf2-5ba0-551d-a229-4dd810d0b0e7', 'be2d5f1e-4e9f-5850-8c75-2298891d7e3f', 'es', 'Sol de la Mañana · Hito Cajón · San Pedro de Atacama', 'Salida temprano para visitar los géiseres de Sol de la Mañana, ubicados a casi 5.000 metros sobre el nivel del mar, donde la actividad geotérmica crea fumarolas y pozas de barro hirviendo. Continuación hacia las Termas de Polques, donde podrás relajarte en aguas termales naturales. Luego cruzarás el surrealista Desierto Dalí y visitarás la Laguna Verde y la Laguna Blanca al pie del volcán Licancabur. Traslado en vehículo chileno desde la frontera boliviana (Hito Cajón) hacia San Pedro de Atacama antes de las 17:00 hrs.', 'Desayuno · Almuerzo · Cóctel', '- Tasas fronterizas y migratorias
