insert into public.day_block_translations (id, block_id, lang, title, description, includes, excludes, reviewed) values ('ab759099-7476-5c02-8371-3437e3f8cd27', '1da549dd-2518-5fc9-a33c-e3026809819a', 'es', 'Salar de Uyuni · Cóctel al Atardecer', 'Visita el pueblo artesanal de Colchani antes de ingresar al inmenso Salar de Uyuni. Disfruta de un almuerzo en medio del salar y luego explora la famosa Isla Incahuasi, hogar de cactus gigantes y formaciones de coral fosilizado. Almuerzo tipo apthapi en el salar.Luego continuaremos hacia las impresionantes Lagunas Altiplánicas — Cañapa, Ramaditas, Honda y Hedionda — hábitat natural de cientos de flamencos dentro de un extraordinario paisaje andino. Posteriormente cruzaremos el Desierto de Siloli, rodeado de volcanes de colores y extensas planicies de altura.
