insert into public.day_blocks (id, code, route_from, route_to, hotel_service_id, default_day_position, status) values ('c6ed468c-e322-5a30-aaac-008f36d0ae3e', 'DAY_c6ed468ce3225a30aaac', 'SPA', NULL, '9fcea26f-f535-501a-9508-669b2826c68a', 1, 'pendiente') on conflict do nothing;
insert into public.day_block_translations (id, block_id, lang, title, description, includes, excludes, reviewed) values ('6ae2dfd1-1217-5949-848e-0a8cb491dcd5', 'c6ed468c-e322-5a30-aaac-008f36d0ae3e', 'es', 'Lagunas Altiplánicas · Desierto de Siloli', 'Salida desde San Pedro de Atacama (Chile), cruzando la frontera por Hito Cajón, donde comenzará la travesía en 4x4 por el altiplano boliviano. Durante el recorrido visitarán la Laguna Blanca, la Laguna Verde, el Desierto de Dalí, los Géiseres Sol de la Mañana (4.900 msnm), uno de los campos geotérmicos más altos del mundo, y la impactante Laguna Colorada (4.278 msnm), importante hábitat de flamencos andinos. La ruta continúa por el Desierto de Siloli y por las hermosas lagunas Cañapa y Hedionda, dos joyas del altiplano rodeadas de volcanes y paisajes de gran altura, reconocidas por su belleza natural y por la presencia de flamencos. Al final del día, llegada al alojamiento en el tradicional pueblo minero de San Cristóbal.
