insert into public.day_block_translations (id, block_id, lang, title, description, includes, excludes, reviewed) values ('1b1cf550-8e07-5cb4-9f23-c1c0382021b5', '4807af0a-ed58-5cfd-b267-1722f8349468', 'es', 'Salar de Uyuni · Cóctel al Atardecer', 'Visita al pueblo artesanal de Colchani antes de ingresar al inmenso Salar de Uyuni. Durante la jornada disfrutarán de un almuerzo tipo apthapi en medio del salar y luego explorarán la famosa Isla Incahuasi, hogar de cactus gigantes y antiguas formaciones de coral fosilizado. Más tarde, vivirán la magia del salar con un cóctel al atardecer, en uno de los escenarios más impresionantes de Bolivia.
